    h, w = len(grid), len(grid[0])
    # The background is the most frequent color.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            part = []
            while q:
                y, x = q.pop()
                part.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, part))

    # Longest non-background component is the line/bend color key.
    key_color, key = max(comps, key=lambda z: len(z[1]))
    out = [row[:] for row in grid]
    targets = [p for p in comps if p[0] != key_color]
    if targets:
