def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            part = []
            while q:
                y, x = q.pop()
                part.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, part))

    # A long, connected line/bend is the color key. Recolor the closest
    # separate object to that key, leaving all other objects unchanged.
    key_color, key = max(comps, key=lambda item: len(item[1]))
    remaining = [item for item in comps if item[1] is not key]
    target = min(remaining, key=lambda item: min(
        abs(y - a) + abs(x - b)
        for y, x in item[1] for a, b in key
    ))

    out = [row[:] for row in grid]
    for r, c in target[1]:
        out[r][c] = key_color
    return out
